package org.sigf.services;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import java.sql.*; import java.time.LocalDate; import java.math.*; import java.util.*;
public final class InventoryService {
 private final Database db; public InventoryService(Database db){this.db=db;}
 public record Product(long id,String code,String name,BigDecimal price,int stock,boolean active,int minimum) {}
 public List<Product> products(String search) throws SQLException { List<Product> out=new ArrayList<>(); try(Connection c=db.connection();PreparedStatement s=c.prepareStatement("select p.id,p.code,p.name,p.sale_price,coalesce(sum(b.quantity),0),p.active,p.minimum_stock from product p left join batch b on b.product_id=p.id where p.name ilike ? or p.code ilike ? or coalesce(p.barcode,'') ilike ? group by p.id order by p.name")){for(int i=1;i<=3;i++)s.setString(i,"%"+search+"%");try(ResultSet r=s.executeQuery()){while(r.next())out.add(new Product(r.getLong(1),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getInt(5),r.getBoolean(6),r.getInt(7)));}} return out; }
 public void saveProduct(Security.User u,Long id,String code,String name,BigDecimal price,int minimum) throws SQLException {u.admin();if(code.isBlank()||name.isBlank()||price.signum()<0||minimum<0)throw new IllegalArgumentException("Datos de producto inválidos"); price=price.setScale(2,RoundingMode.UNNECESSARY); String sql=id==null?"insert into product(code,name,sale_price,minimum_stock) values (?,?,?,?)":"update product set code=?,name=?,sale_price=?,minimum_stock=? where id=?"; try(Connection c=db.connection();PreparedStatement s=c.prepareStatement(sql)){Security.verify(c,u,true);s.setString(1,code);s.setString(2,name);s.setBigDecimal(3,price);s.setInt(4,minimum);if(id!=null)s.setLong(5,id);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Producto no encontrado");} }
 public long receive(Security.User u,long product,String lot,LocalDate expiry,int quantity,BigDecimal cost) throws SQLException {return receive(u,product,lot,expiry,quantity,cost,null);}
 public long receive(Security.User u,long product,String lot,LocalDate expiry,int quantity,BigDecimal cost,Long supplier) throws SQLException {u.admin();if(lot==null||lot.isBlank()||expiry==null||!expiry.isAfter(LocalDate.now())||quantity<=0||cost==null||cost.signum()<0)throw new IllegalArgumentException("Lote, vencimiento, cantidad o costo inválido");var request=new PurchaseRecovery.Pending(UUID.randomUUID(),supplier,List.of(new PurchaseItem(product,lot,expiry,quantity,cost)));PurchaseRecovery recovery=new PurchaseRecovery(db);recovery.save(u,request);long purchase=recovery.resolve(u,request.id());recovery.acknowledge(u,request.id(),false);return purchase;}

 public record ProductDetails(String code,String barcode,String name,String category,String description,String presentation,String laboratory,BigDecimal cost,BigDecimal price,int minimum,boolean active,BigDecimal taxRate) {}
 public ProductDetails details(long id)throws SQLException {try(Connection c=db.connection();PreparedStatement s=c.prepareStatement("select code,coalesce(barcode,''),name,coalesce(category,''),coalesce(description,''),coalesce(presentation,''),coalesce(laboratory,''),purchase_price,sale_price,minimum_stock,active,tax_rate from product where id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("Producto inexistente");return new ProductDetails(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getInt(10),r.getBoolean(11),r.getBigDecimal(12));}}}
 public void saveDetails(Security.User u,Long id,ProductDetails p)throws SQLException {u.admin();if(p.code().isBlank()||p.name().isBlank()||p.minimum()<0||p.cost().signum()<0||p.price().signum()<0||p.taxRate()==null||p.taxRate().signum()<0||p.taxRate().compareTo(BigDecimal.ONE)>0)throw new IllegalArgumentException("Datos de producto inválidos");BigDecimal cost=p.cost().setScale(2,RoundingMode.UNNECESSARY),price=p.price().setScale(2,RoundingMode.UNNECESSARY);String sql=id==null?"insert into product(code,barcode,name,category,description,presentation,laboratory,purchase_price,sale_price,minimum_stock,active,tax_rate) values(?,?,?,?,?,?,?,?,?,?,?,?)":"update product set code=?,barcode=?,name=?,category=?,description=?,presentation=?,laboratory=?,purchase_price=?,sale_price=?,minimum_stock=?,active=?,tax_rate=? where id=?";try(Connection c=db.connection()){c.setAutoCommit(false);try(PreparedStatement s=c.prepareStatement(sql)){Security.verify(c,u,true);s.setString(1,p.code().trim());s.setString(2,p.barcode().isBlank()?null:p.barcode().trim());s.setString(3,p.name().trim());s.setString(4,p.category());s.setString(5,p.description());s.setString(6,p.presentation());s.setString(7,p.laboratory());s.setBigDecimal(8,cost);s.setBigDecimal(9,price);s.setInt(10,p.minimum());s.setBoolean(11,p.active());s.setBigDecimal(12,p.taxRate().setScale(5,RoundingMode.UNNECESSARY));if(id!=null)s.setLong(13,id);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Producto inexistente");try(PreparedStatement a=c.prepareStatement("insert into audit_log(actor_id,action,details) values(?,'PRODUCT_CHANGE',?)")){a.setLong(1,u.id());a.setString(2,p.code());a.executeUpdate();}c.commit();}catch(Exception ex){c.rollback();throw ex;}}}
 public long sell(Security.User u,long product,int quantity,UUID request) throws SQLException {return new Operations(db).sell(u,List.of(new CartItem(product,quantity)),null,"CASH",request).id();}
}